"""Read ids.txt and print the next order id."""

import itertools


def decode_base36(s: str) -> int:
    """Decode a base-36 string to an integer."""
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = 0
    for ch in s:
        result = result * 36 + digits.index(ch.upper())
    return result


def encode_base36(n: int, width: int) -> str:
    """Encode an integer as a zero-padded base-36 string of the given width."""
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n == 0:
        return digits[0] * width
    result = []
    while n > 0:
        result.append(digits[n % 36])
        n //= 36
    return "".join(reversed(result)).rjust(width, "0")


