def base36_increment(s: str) -> str:
    """Increment a base36-encoded string by 1, preserving length."""
    chars = list(s)
    for i in range(len(chars) - 1, -1, -1):
        idx = BASE36.index(chars[i])
        if idx < 35:
            chars[i] = BASE36[idx + 1]
            return "".join(chars)
        chars[i] = BASE36[0]
    # Overflow: all positions wrapped — return the length with leading zero replaced
    # (not expected for this use case, but handled gracefully)
    return BASE36[0] * len(s)


