"""Print the next order id to stdout."""

from __future__ import annotations

import pathlib


def base36_encode(n: int, width: int = 4) -> str:
    """Encode an integer as a zero-padded base-36 string."""
    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n == 0:
        return digits[0] * width
    result: list[str] = []
    while n > 0:
        result.append(digits[n % 36])
        n //= 36
    return "".join(reversed(result)).rjust(width, "0")


def base36_decode(s: str) -> int:
    """Decode a base-36 string to an integer."""
    return int(s, 36)


def main() -> None:
    ids_path = pathlib.Path("ids.txt")
    last_id: str | None = None

    if ids_path.exists():
        for line in ids_path.read_text().strip().splitlines():
            line = line.strip()
            if line.startswith("ORD-") and len(line) == 8:
                last_id = line

    if last_id is not None:
        suffix = last_id[4:]
        n = base36_decode(suffix) + 1
    else:
        n = 0

    next_suffix = base36_encode(n, width=4)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

