#!/usr/bin/env python3
"""Reads ids.txt and prints the next order id."""

import sys

BASE36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'


def base36_decode(s: str) -> int:
    """Decode a base36 string to an integer."""
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch.upper())
    return n


def base36_encode(n: int) -> str:
    """Encode an integer to a base36 string (uppercase, no leading zeros)."""
    if n == 0:
        return '0'
    chars = []
    while n > 0:
        chars.append(BASE36[n % 36])
        n //= 36
    return ''.join(reversed(chars))


def next_id(current: str) -> str:
    """Given an id like 'ORD-243G', return the next id."""
    suffix = current.split('-')[1]
    num = base36_decode(suffix)
    next_num = num + 1
    next_suffix = base36_encode(next_num).zfill(4)[-4:]
    return f'ORD-{next_suffix}'


def main() -> None:
    with open('ids.txt') as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        print('ORD-0000')
        return

    last_id = lines[-1]
    print(next_id(last_id))


if __name__ == '__main__':
    main()

