#!/usr/bin/env python3

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def next_id(current: str) -> str:
    """Return the next order id after the given one."""
    if not current.startswith("ORD-"):
        raise ValueError(f"Unexpected id format: {current}")
    suffix = current[4:]
    if len(suffix) != 4:
        raise ValueError(f"Unexpected suffix length: {suffix}")

    # Parse the 4-character suffix as a base-36 number
    value = 0
    for ch in suffix:
        value = value * 36 + BASE36.index(ch)

    # Increment
    value += 1

    # Encode back to 4-character base-36
    result = ""
    for _ in range(4):
        result = BASE36[value % 36] + result
        value //= 36

    return f"ORD-{result}"


def main():
    try:
        with open("ids.txt") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("ids.txt not found", file=sys.stderr)
        sys.exit(1)

    # Find the last non-empty line with an id
    last_id = None
    for line in reversed(lines):
        stripped = line.strip()
        if stripped and stripped.startswith("ORD-"):
            last_id = stripped
            break

    if last_id is None:
        print("No valid order ids found in ids.txt", file=sys.stderr)
        sys.exit(1)

    print(next_id(last_id))


if __name__ == "__main__":
    main()

