"""Print the next order id to stdout.

Reads ids.txt (one id per line, most recent last), increments the
last-issued id positionally in the restricted alphabet, and prints
the result as ORD-XXXX.
"""

ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"
BASE = len(ALPHABET)  # 32
CHAR_TO_IDX = {c: i for i, c in enumerate(ALPHABET)}


def _decode(s: str) -> int:
    """Convert a 4-character id suffix to an integer (base-32 positional)."""
    value = 0
    for ch in s:
        value = value * BASE + CHAR_TO_IDX[ch]
    return value


def _encode(n: int) -> str:
    """Convert an integer to a 4-character id suffix (zero-padded)."""
    chars = []
    for _ in range(4):
        chars.append(ALPHABET[n % BASE])
        n //= BASE
    return "".join(reversed(chars))


def next_id() -> str:
    """Return the next order id string (e.g. 'ORD-243H')."""
    with open("ids.txt") as f:
        lines = [line.strip() for line in f if line.strip()]
    if not lines:
        # Start from zero if file is empty
        return "ORD-" + _encode(0)
    last = lines[-1]
    suffix = last.removeprefix("ORD-")
    n = _decode(suffix)
    return "ORD-" + _encode(n + 1)


if __name__ == "__main__":
    print(next_id())
