"""Read attendees.txt, sort case-insensitively, and write roster.txt."""

def main():
    names = []
    with open("attendees.txt", encoding="utf-8") as handle:
        for line in handle:
            stripped = line.strip()
            if stripped:
                names.append(stripped)

    names.sort(key=str.casefold)

    with open("roster.txt", "w", encoding="utf-8") as out:
        for name in names:
            out.write(name + "\n")


if __name__ == "__main__":
    main()

