#!/usr/bin/env python3
"""Validate orders.json: every order must have a non-empty id and amount > 0."""

import json
import sys


def main():
    try:
        with open("orders.json") as f:
            orders = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"ERROR: could not read orders.json — {e}")
        sys.exit(1)

    if not isinstance(orders, list):
        print("ERROR: orders.json must be a JSON list")
        sys.exit(1)

    has_problem = False
    for i, order in enumerate(orders):
        if not isinstance(order, dict):
            print(f"ERROR: entry #{i} is not an object ({order!r})")
            has_problem = True
            continue

        oid = order.get("id", "")
        if not oid or not isinstance(oid, str) or oid.strip() == "":
            print(f"ERROR: order #{i} has a missing or empty id ({oid!r})")
            has_problem = True

        amount = order.get("amount")
        if not isinstance(amount, (int, float)):
            print(f"ERROR: order id={oid!r} has a non-numeric amount ({amount!r})")
            has_problem = True
        elif amount <= 0:
            print(f"ERROR: order id={oid!r} has amount {amount} (must be > 0)")
            has_problem = True

    if has_problem:
        sys.exit(1)


if __name__ == "__main__":
    main()

