import json
import sys

def main():
    try:
        with open("orders.json") as f:
            orders = json.load(f)
    except FileNotFoundError:
        print("ERROR: orders.json not found")
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"ERROR: orders.json is not valid JSON: {e}")
        sys.exit(1)

    if not isinstance(orders, list):
        print("ERROR: orders.json must be a list")
        sys.exit(1)

    has_errors = False
    for order in orders:
        if not isinstance(order, dict):
            print(f"ERROR: order is not an object: {order}")
            has_errors = True
            continue

        oid = order.get("id")
        amount = order.get("amount")

        if not oid:
            print(f"ERROR: order has empty or missing id")
            has_errors = True

        if amount is None or not isinstance(amount, (int, float)):
            print(f"ERROR: order {oid} has invalid amount")
            has_errors = True
        elif amount <= 0:
            print(f"ERROR: order {oid} has amount {amount} (must be > 0)")
            has_errors = True

    if has_errors:
        sys.exit(1)

if __name__ == "__main__":
    main()

