"""Validate order intake before the nightly billing job runs."""

import json


def main() -> None:
    with open("orders.json", encoding="utf-8") as f:
        orders = json.load(f)

    problems: list[str] = []

    for order in orders:
        oid = order.get("id", "")
        amount = order.get("amount", 0)

        if not oid:
            problems.append(f"order with amount {amount} has an empty id")
        if amount <= 0:
            problems.append(f"order {oid} has a non-positive amount: {amount}")

    for problem in problems:
        print(problem)

    print(f"checked {len(orders)} orders, {len(problems)} problem(s)")


if __name__ == "__main__":
    main()

