#!/usr/bin/env python3
"""Read events.jsonl, remove duplicates by event_id, write deduped.jsonl."""

import json

def main():
    seen = set()
    deduped = []

    with open("events.jsonl") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            record = json.loads(line)
            eid = record["event_id"]
            if eid not in seen:
                seen.add(eid)
                deduped.append(record)

    with open("deduped.jsonl", "w") as f:
        for record in deduped:
            f.write(json.dumps(record) + "\n")

if __name__ == "__main__":
    main()

