#!/usr/bin/env python3
"""Read every .txt file in inbox/ and write report.txt with entries, total, and average."""

import os
import glob

def main():
    measurements = []

    # Read all .txt files in the inbox/ directory
    inbox_dir = "inbox"
    txt_files = glob.glob(os.path.join(inbox_dir, "*.txt"))

    for filepath in sorted(txt_files):
        with open(filepath) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                # Each line holds one integer measurement
                # The format is <index>\t<value> but we just parse the integer
                parts = line.split("\t")
                for part in parts:
                    part = part.strip()
                    if part:
                        try:
                            measurements.append(int(part))
                        except ValueError:
                            pass

    # Filter to only the actual measurements (not the index numbers)
    # Looking at the data, the format is: index\tvalue
    # So we need to take the second column
    measurements = []
    for filepath in sorted(txt_files):
        with open(filepath) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                parts = line.split("\t")
                if len(parts) >= 2:
                    val = parts[1].strip()
                    if val:
                        try:
                            measurements.append(int(val))
                        except ValueError:
                            pass

    n = len(measurements)
    total = sum(measurements)
    average = total / n if n > 0 else 0.0

    with open("report.txt", "w") as out:
        out.write(f"entries {n}\n")
        out.write(f"total {total}\n")
        out.write(f"average {average:.2f}\n")

    print(f"Wrote report.txt: entries={n}, total={total}, average={average:.2f}")

if __name__ == "__main__":
    main()

