#!/usr/bin/env python3
"""Read entries.txt (one key=value per line) and write config.json mapping each key to its value."""

import json
import os

ROOT = os.path.dirname(os.path.abspath(__file__))


def main():
    entries = {}
    with open(os.path.join(ROOT, "entries.txt"), "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            key, _, value = line.partition("=")
            if not _:
                raise ValueError(f"Invalid entry (missing '='): {line!r}")
            entries[key.strip()] = value

    with open(os.path.join(ROOT, "config.json"), "w", encoding="utf-8") as f:
        json.dump(entries, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main()

