#!/usr/bin/env python3
"""Walk release/, compute SHA-256 digests, write manifest.json."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST = Path("manifest.json")


def main() -> None:
    manifest: dict[str, str] = {}

    # Walk release/ collecting files (sort for deterministic output)
    for path in sorted(RELEASE_DIR.rglob("*")):
        if not path.is_file():
            continue
        rel_path = str(path.relative_to(RELEASE_DIR.parent))
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        manifest[rel_path] = digest

    MANIFEST.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n")
    print(f"wrote {MANIFEST} with {len(manifest)} entries")


if __name__ == "__main__":
    main()

