#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for all files under release/."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_FILE = "manifest.json"


def sha256_digest(filepath: str) -> str:
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(filepath, "rb") as f:
        while True:
            chunk = f.read(65536)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def main():
    manifest = {}

    if not os.path.isdir(RELEASE_DIR):
        print(f"Error: '{RELEASE_DIR}' directory not found.")
        return

    for root, dirs, files in os.walk(RELEASE_DIR):
        for filename in files:
            full_path = os.path.join(root, filename)
            rel_path = os.path.relpath(full_path, RELEASE_DIR)
            # Use forward slashes for consistency
            rel_path = rel_path.replace(os.sep, "/")
            manifest[rel_path] = sha256_digest(full_path)

    with open(MANIFEST_FILE, "w") as f:
        json.dump(manifest, f, indent=2)

    print(f"Written {MANIFEST_FILE} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()
