#!/usr/bin/env python3
"""List report files under reports/ in report-number order (natural sort)."""

import os
import re

REPORTS_DIR = "reports"


def report_number(filename: str) -> int:
    """Extract the numeric report number from a filename like 'report-<n>.txt'."""
    m = re.search(r"report-(\d+)\.txt$", filename)
    if m:
        return int(m.group(1))
    return -1


def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return

    reports = [e for e in entries if re.match(r"report-\d+\.txt$", e)]
    reports.sort(key=report_number)

    for name in reports:
        print(name)


if __name__ == "__main__":
    main()

