#!/usr/bin/env python3
"""Print report file names under reports/, one per line, in report order."""

import os
import re

REPORTS_DIR = "reports"

pattern = re.compile(r"^report-(\d+)\.txt$")

def report_order(filename: str) -> int:
    """Extract the numeric ordering key from a report filename."""
    m = pattern.match(filename)
    if m is None:
        return float("inf")  # non-conforming files sort last
    return int(m.group(1))

files = sorted(
    (f for f in os.listdir(REPORTS_DIR) if os.path.isfile(os.path.join(REPORTS_DIR, f))),
    key=report_order,
)

for f in files:
    print(f)

