import glob
import re
from collections import Counter

def main():
    word_counts = Counter()

    # Find all .txt files under docs/ recursively
    for filepath in glob.glob('docs/**/*.txt', recursive=True):
        with open(filepath, 'r', encoding='utf-8') as f:
            text = f.read()
            # Split into words
            for word in text.split():
                # Lowercase and strip punctuation .,;:!? from edges
                cleaned = word.lower().strip('.,;:!?')
                if cleaned:
                    word_counts[cleaned] += 1

    # Write sorted counts to counts.txt
    with open('counts.txt', 'w', encoding='utf-8') as f:
        for word in sorted(word_counts):
            f.write(f"{word} {word_counts[word]}\n")

if __name__ == '__main__':
    main()

