"""Read every .txt file under docs/, count word occurrences, and write counts.txt."""

import glob
import os
import re

PUNCTUATION = r'[.,;:!?]'
COUNT_FILE = 'counts.txt'


def clean_word(word: str) -> str:
    """Lowercase and strip punctuation from word edges."""
    return word.lower().strip(PUNCTUATION)


def main():
    counts: dict[str, int] = {}

    for txt_path in sorted(glob.glob('docs/**/*.txt', recursive=True)):
        if not os.path.isfile(txt_path):
            continue
        with open(txt_path, encoding='utf-8') as f:
            content = f.read()
        words = content.split()
        for raw in words:
            w = clean_word(raw)
            if w:
                counts[w] = counts.get(w, 0) + 1

    with open(COUNT_FILE, 'w', encoding='utf-8') as out:
        for word in sorted(counts):
            out.write(f'{word} {counts[word]}\n')

    print(f'Wrote {COUNT_FILE} with {len(counts)} unique words.')


if __name__ == '__main__':
    main()

