"""Count word occurrences in .txt files under docs/ and write counts.txt."""

import os
import re
from collections import Counter

PUNCTUATION = ".,;:!?"
DOCS_DIR = "docs"
OUTPUT_FILE = "counts.txt"


def main():
    counter = Counter()

    for filename in os.listdir(DOCS_DIR):
        if not filename.endswith(".txt"):
            continue
        path = os.path.join(DOCS_DIR, filename)
        with open(path, encoding="utf-8") as f:
            for line in f:
                for raw_word in line.split():
                    word = raw_word.strip(PUNCTUATION).lower()
                    if word:
                        counter[word] += 1

    with open(OUTPUT_FILE, "w", encoding="utf-8") as f:
        for word in sorted(counter):
            f.write(f"{word} {counter[word]}\n")

    print(f"Wrote {len(counter)} unique words to {OUTPUT_FILE}")


if __name__ == "__main__":
    main()

