"""Count word occurrences in all .txt files under docs/."""
import glob
import os

PUNCTUATION = ".,;:!?"
OUTPUT_FILE = "counts.txt"


def strip_edge_punctuation(word):
    """Strip punctuation characters from the edges of a word."""
    while word and word[0] in PUNCTUATION:
        word = word[1:]
    while word and word[-1] in PUNCTUATION:
        word = word[:-1]
    return word


def main():
    counts = {}

    for txt_path in glob.glob("docs/**/*.txt", recursive=True):
        with open(txt_path, encoding="utf-8") as f:
            content = f.read()

        for raw_word in content.split():
            word = strip_edge_punctuation(raw_word.lower())
            if word:
                counts[word] = counts.get(word, 0) + 1

    with open(OUTPUT_FILE, "w", encoding="utf-8") as f:
        for word in sorted(counts):
            f.write(f"{word} {counts[word]}\n")

    print(f"Wrote {len(counts)} unique words to {OUTPUT_FILE}")


if __name__ == "__main__":
    main()

