"""Count word frequencies across all .txt files under docs/."""
import os
import re
from collections import Counter

PUNCTUATION = set(".,;:!?")

def strip_punctuation(word: str) -> str:
    """Strip punctuation characters from both edges of a word."""
    return word.strip("".join(PUNCTUATION))

def main():
    counter: Counter[str] = Counter()
    docs_dir = "docs"

    for root, _dirs, files in os.walk(docs_dir):
        for filename in files:
            if not filename.endswith(".txt"):
                continue
            path = os.path.join(root, filename)
            with open(path, encoding="utf-8") as f:
                text = f.read()
            words = text.split()
            for raw in words:
                cleaned = strip_punctuation(raw).lower()
                if cleaned:
                    counter[cleaned] += 1

    with open("counts.txt", "w", encoding="utf-8") as out:
        for word in sorted(counter):
            out.write(f"{word} {counter[word]}\n")

if __name__ == "__main__":
    main()
