    validate(base | {"bogus": 1, "priority": "low"})
except ValueError as e:
    print("unknown field still rejected:", e)
try:
    validate({"title": "x", "created_at": "y", "priority": "high"})
except ValueError as e:
    print("missing field still rejected:", e)
print("ALL CHECKS PASSED")
EOF

