#!/usr/bin/env python3
"""Rotate entries in app.log older than 7 days before AS_OF to archive.log."""

import sys
from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Parse leading 'YYYY-MM-DD HH:MM:SS' from a log line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of_ts = int(sys.argv[1])
    as_of = datetime.fromtimestamp(as_of_ts, tz=timezone.utc)
    cutoff = as_of - timedelta(days=7)  # strictly older than 7 days before AS_OF

    keep: list[str] = []
    archive: list[str] = []

    with open("app.log", "r") as f:
        for line in f:
            line = line.rstrip("\n")
            if not line:
                continue
            dt = parse_timestamp(line)
            if dt is not None and dt < cutoff:
                archive.append(line)
            else:
                keep.append(line)

    # Append to archive.log in original order
    if archive:
        with open("archive.log", "a") as f:
            for entry in archive:
                f.write(entry + "\n")

    # Rewrite app.log with remaining entries in original order
    with open("app.log", "w") as f:
        for entry in keep:
            f.write(entry + "\n")


if __name__ == "__main__":
    main()

