"""Rotate entries from app.log to archive.log based on age.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line of app.log starts with
a timestamp formatted YYYY-MM-DD HH:MM:SS followed by a message. Entries whose
timestamp is strictly older than 7 days before AS_OF are moved to archive.log
(appended, preserving order). app.log is rewritten with the remaining entries.
"""

import sys
import datetime


def parse_line_timestamp(line: str) -> datetime.datetime | None:
    """Extract the YYYY-MM-DD HH:MM:SS timestamp from the start of a line."""
    if len(line) < 19:
        return None
    try:
        return datetime.datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    cutoff = datetime.datetime.fromtimestamp(
        as_of - 7 * 24 * 3600, tz=datetime.timezone.utc
    )

    # Read all lines from app.log
    try:
        with open("app.log", "r") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print("Error: app.log not found.", file=sys.stderr)
        sys.exit(1)

    keep_lines: list[str] = []
    archive_lines: list[str] = []

    for line in lines:
        dt = parse_line_timestamp(line)
        if dt is not None:
            # Compare naive datetimes: both are "YYYY-MM-DD HH:MM:SS" without tz info
            dt_utc = dt.replace(tzinfo=datetime.timezone.utc)
            if dt_utc < cutoff:
                archive_lines.append(line)
            else:
                keep_lines.append(line)
        else:
            # Lines without a valid timestamp are kept in app.log
            keep_lines.append(line)

    # Append archive lines to archive.log
    if archive_lines:
        with open("archive.log", "a") as f:
            f.writelines(archive_lines)

    # Rewrite app.log with remaining lines
    with open("app.log", "w") as f:
        f.writelines(keep_lines)


if __name__ == "__main__":
    main()

