#!/usr/bin/env python3
"""Rotate old entries from app.log to archive.log based on a cutoff date."""

import sys
from datetime import datetime, timedelta, timezone


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff = datetime.fromtimestamp(as_of, tz=timezone.utc) - timedelta(days=7)

    with open("app.log", "r") as f:
        lines = f.readlines()

    old_lines = []   # strictly older than 7 days before AS_OF
    keep_lines = []  # remaining

    for line in lines:
        line = line.rstrip("\n")
        if not line.strip():
            continue
        # Parse the timestamp prefix: YYYY-MM-DD HH:MM:SS
        ts_str = line[:19]
        try:
            entry_dt = datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
        except ValueError:
            # If timestamp can't be parsed, keep the line in app.log
            keep_lines.append(line)
            continue

        if entry_dt < cutoff:
            old_lines.append(line)
        else:
            keep_lines.append(line)

    # Append old entries to archive.log preserving order
    if old_lines:
        with open("archive.log", "a") as f:
            for line in old_lines:
                f.write(line + "\n")

    # Rewrite app.log with remaining entries
    with open("app.log", "w") as f:
        for line in keep_lines:
            f.write(line + "\n")


if __name__ == "__main__":
    main()

