LOG_FILE = "app.log"
ARCHIVE_FILE = "archive.log"
DAYS = 7


def parse_entry(line: str):
    """Parse a log line into (unix_timestamp, raw_line) or None."""
    line = line.rstrip("\n")
    if not line:
        return None
    ts_str = line[:19]  # "YYYY-MM-DD HH:MM:SS"
    try:
        dt = datetime.datetime.strptime(ts_str, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None
    # Build a timezone-naive datetime for comparison
    epoch = datetime.datetime(1970, 1, 1)
    unix_ts = (dt - epoch).total_seconds()
    return unix_ts, line


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff = as_of - DAYS * 24 * 3600

    # Read all entries
    archive_lines = []
    app_lines = []
    try:
        with open(LOG_FILE) as f:
            for line in f:
                parsed = parse_entry(line)
                if parsed is None:
                    continue
                ts, text = parsed
                if ts < cutoff:
                    archive_lines.append(text)
                else:
                    app_lines.append(text)
    except FileNotFoundError:
        print(f"{LOG_FILE} not found, nothing to rotate.", file=sys.stderr)
        sys.exit(1)

    # Append to archive.log (preserving order)
    if archive_lines:
        with open(ARCHIVE_FILE, "a") as f:
            for line in archive_lines:
                f.write(line + "\n")

    # Rewrite app.log with remaining entries
    with open(LOG_FILE, "w") as f:
        for line in app_lines:
            f.write(line + "\n")


if __name__ == "__main__":
    main()

