"""Rotate old entries from app.log into archive.log.

Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every entry whose timestamp
is strictly older than 7 days before AS_OF is moved to archive.log.
"""

import datetime
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent
APP_LOG = REPO_ROOT / "app.log"
ARCHIVE_LOG = REPO_ROOT / "archive.log"


def parse_timestamp(line: str) -> datetime.datetime | None:
    """Parse a leading 'YYYY-MM-DD HH:MM:SS' from line, return UTC datetime or None."""
    if len(line) < 19:
        return None
    try:
        return datetime.datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=datetime.timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"AS_OF must be an integer Unix timestamp, got: {sys.argv[1]}", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.datetime.fromtimestamp(as_of, tz=datetime.timezone.utc)
    cutoff = as_of_dt - datetime.timedelta(days=7)

    if not APP_LOG.exists():
        print("app.log not found", file=sys.stderr)
        sys.exit(1)

    lines = APP_LOG.read_text(encoding="utf-8").splitlines(keepends=True)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        stripped = line.rstrip("\n").rstrip("\r")
        if not stripped:
            # Preserve blank lines in place
            keep.append(line)
            continue
        entry_ts = parse_timestamp(stripped)
        if entry_ts is None:
            # Lines without a parseable timestamp stay in app.log
            keep.append(line)
        elif entry_ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    # Append to archive.log
    if archive:
        with ARCHIVE_LOG.open("a", encoding="utf-8") as f:
            f.writelines(archive)

    # Rewrite app.log
    APP_LOG.write_text("".join(keep), encoding="utf-8")


if __name__ == "__main__":
    main()

